const xml2js = require('xml2js');
let responseJson = null;

xml2js.parseString(pm.response.text(), { explicitArray: false }, (err, result) => {
    if (!err) {
        responseJson = result;
    }
});

pm.test("1. Status code is 200 OK", function () {
    pm.response.to.have.status(200);
});

pm.test("2. Response status line is OK", function () {
    pm.response.to.have.status("OK");
});

pm.test("3. Header Content-Type is present", function () {
    pm.response.to.have.header("Content-Type");
});

pm.test("4. Content-Type is text/xml", function () {
    pm.expect(pm.response.headers.get("Content-Type")).to.include("text/xml");
});

pm.test("5. Server header is present", function () {
    pm.response.to.have.header("Server");
});

pm.test("6. Response time is less than 2000ms", function () {
    pm.expect(pm.response.responseTime).to.be.below(2000);
});

pm.test("7. Response body is not empty", function () {
    pm.expect(pm.response.text()).to.not.be.empty;
});

pm.test("8. Response XML contains soap:Envelope", function () {
    pm.expect(pm.response.text()).to.include("soap:Envelope");
});

pm.test("9. Response contains IsValidISBN13Result tag", function () {
    pm.expect(pm.response.text()).to.include("m:IsValidISBN13Result");
});

pm.test("10. ISBN13 validation result is true", function () {
    const resultValue = responseJson['soap:Envelope']['soap:Body']['m:IsValidISBN13Response']['m:IsValidISBN13Result'];
    pm.expect(resultValue).to.equal('true');
});

